void unit_test_delete_bt_node_with_only_right_child_left_parent(void) {
    // Build a tree where:
    // - Root is not NULL (bypass first condition)
    // - Node to delete has left child NULL and right child NOT NULL (temp->llink == NULL && temp->rlink != NULL)
    // - Node is NOT the root (temp != *root)
    // - Node is the left child of its parent (prev->llink == temp)
    // - Node value exists and is found in search loop (temp->data == ele)

    // Tree structure:
    //       50
    //      /  \n    //    30    70
    //     \n    //     40   <-- delete this node (has only right child NULL? Actually 40 has no children)
    // Wait, we need a node with only right child. Let's adjust:
    //       50
    //      /  \n    //    30    70
    //     \n    //     40
    //      \n    //      45  <-- delete 40 (has only right child 45)

    // But we need 40 to be found in search. Let's build tree with insert_bt.
    // Values to insert: 50, 30, 40, 45
    int values[] = {50, 30, 40, 45};
    node* root = helper_build_tree(values, 4);
    TEST_ASSERT_NOT_NULL(root);

    // Verify tree structure before deletion
    // Inorder should be: 30 40 45 50
    helper_assert_tree_inorder(root, "30 40 45 50 ");

    // Delete node 40 which has only right child 45
    // Conditions for path 9:
    // 1. *root != NULL (true)
    // 2. temp != NULL in loop (true)
    // 3. temp->data == ele (true when ele=40)
    // 4. temp->llink == NULL && temp->rlink != NULL (true for node 40)
    // 5. temp != *root (40 is not root)
    // 6. prev->llink == temp (30's left is NULL, right is 40, so prev->rlink == temp)
    // Wait! For path 9 we need prev->llink == temp, not prev->rlink == temp.
    // Let's rebuild tree so that node to delete is left child of its parent.

    // New tree structure:
    //       50
    //      /  \n    //    40    70
    //   /
    //  35      <-- delete 35 (has only right child NULL? Actually 35 has no children)
    // We need node with only right child. Let's do:
    //       50
    //      /  \n    //    40    70
    //   /
    //  35
    //   \n    //   38     <-- delete 35 (has only right child 38)

    // But 35 is left child of 40. Good.
    helper_free_tree(root);

    // Build new tree: 50, 40, 35, 38
    int values2[] = {50, 40, 35, 38};
    root = helper_build_tree(values2, 4);
    TEST_ASSERT_NOT_NULL(root);

    // Verify tree before deletion: inorder should be 35 38 40 50
    helper_assert_tree_inorder(root, "35 38 40 50 ");

    // Now delete node 35 which:
    // - Has left child NULL and right child 38 (temp->llink == NULL && temp->rlink != NULL)
    // - Is left child of node 40 (prev->llink == temp)
    // - Is not root
    delete_bt(&root, 35);

    // After deletion, node 35 should be replaced by its right child 38
    // Tree should now be:
    //       50
    //      /  \n    //    40    70 (70 doesn't exist in our tree, actually right subtree of 50 is empty)
    //   /
    //  38

    // Wait, we didn't insert 70. Let's check actual tree:
    // After inserting 50, 40, 35, 38:
    //       50
    //      /
    //    40
    //   /
    //  35
    //   \n    //   38
    // After deleting 35:
    //       50
    //      /
    //    40
    //   /
    //  38

    // Verify 35 is gone
    helper_assert_search_result(root, 35, 0);

    // Verify 38 still exists
    helper_assert_search_result(root, 38, 1);

    // Verify 40 still exists
    helper_assert_search_result(root, 40, 1);

    // Verify 50 still exists
    helper_assert_search_result(root, 50, 1);

    // Verify inorder traversal: 38 40 50
    helper_assert_tree_inorder(root, "38 40 50 ");

    // Cleanup
    helper_free_tree(root);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_delete_bt_node_with_only_right_child_left_parent);
    return UNITY_END();
}

